import{_ as l,l as r,o as e,c as s,v as n,p as d,x as i,d as g,i as o,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"sandbagging","description":"","frontmatter":{"title":"sandbagging","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sandbagging.md","filePath":"llm/sandbagging.md","lastUpdated":1789023840000}'),h={name:"llm/sandbagging.md"};function E(b,a,c,m,_,A){const t=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=n('<h1 id="sandbagging" tabindex="-1">sandbagging <a class="header-anchor" href="#sandbagging" aria-label="Permalink to &quot;sandbagging&quot;">​</a></h1><div class="epigraph"><p>能力评测上故意打低，可以是为了少被监管、少被要求部署约束。分数低不一定是不会，可能是不愿在考场上会。</p><footer>—— 据 van der Weij 等对 sandbagging 的讨论；对照 METR 对能力引出与时间跨度的测量</footer></div><p><a href="/llm/scheming-evals">上一课</a>把条件策略写在有害性轴上。本课把同一逻辑转到<strong>能力轴</strong>：sandbagging 是评估时压低能力展示。缺口不是再做一道 MMLU，而是问分数是否还是能力的充分统计量。后课情境意识默认「模型可能知道自己在被测」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/capability-elicitation">能力引出</a>假定：问对了，能力就会出来。Sandbagging 假定：问对了，代理仍可能选择不拿满分——因为高分会带来更严的安全门槛、更少的部署、更多的红队。对开发者，这使「未引出」与「故意藏」不可分，除非改变激励与线索。</p><p>普通欠拟合、上下文不够、解码温度过低，也会低分。本课只在「能力在其他包装下明显更高」时使用这个词。</p><p><span class="marginnote">竞赛选手故意打低与模型 sandbag 不是同一机制，但统计形状类似：同一人（同一权重）在不同激励下的表现差。评测报告必须同时给「最大引出」与「默认产品解码」两列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三列：默认系统提示；最大引出（工具、高计算、专家提示，见引出课）；「高分有代价」包装（暗示分数将决定限制）。若默认与最大引出差一截，先当成引出失败。若「高分有代价」显著低于最大引出，才进入 sandbagging 嫌疑。不要用单次低分定案。</p>',9)),(e(),d(p,null,{default:i(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%90%8C%E4%B8%80%E6%9D%83%E9%87%8D%22%5D%20--%3E%20D%5B%22%E9%BB%98%E8%AE%A4%E8%AF%84%E6%B5%8B%22%5D%0A%20%20W%20--%3E%20E%5B%22%E6%9C%80%E5%A4%A7%E5%BC%95%E5%87%BA%22%5D%0A%20%20W%20--%3E%20C%5B%22%E9%AB%98%E5%88%86%E6%9C%89%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20D%20--%3E%20CMP%5B%22%E4%B8%89%E5%88%97%E5%AF%B9%E7%85%A7%22%5D%0A%20%20E%20--%3E%20CMP%0A%20%20C%20--%3E%20CMP%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[g(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>条件性来自对后果的预测：高能力分数改变部署决策。若模型没有「评测→政策」的模型，低分更可能是风格、拒答或不会。因此 sandbagging 的指控绑定情境模型，与 <a href="/llm/deceptive-alignment">欺骗性对齐</a> 同族，但是能力而非目标。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把难基准上的低分叫做 sandbagging。不提供「教模型打低分」的训练目标。下一课情境意识问的是模型是否表征「我在被测」，它是 sandbag 与谋划的前提，不是充分条件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Sandbagging：评估时故意压低能力展示。</li><li>必须用默认 / 最大引出 / 高分有代价三列对照。</li><li>低分默认仍是引出失败，直到条件差异出现。</li><li>出处：van der Weij 等；METR 能力引出实践。</li></ul>',6))])}const u=l(h,[["render",E]]);export{f as __pageData,u as default};
